def isPerfNum(n):
    sum = 0
    for i in range(1, n):
        if n % i == 0:
            sum += i
    return sum == n

def reverse_characters_in_words(s: str) -> str:
    str_list = list(s)
    left = 0
    for index, value in enumerate(str_list):
        if value == ' ':
            right = index - 1
            while left < right:
                str_list[left], str_list[right] = str_list[right], str_list[left]
                left += 1
                right -= 1
            left = index + 1

    right = len(s) - 1
    while left < right:
        str_list[left], str_list[right] = str_list[right], str_list[left]
        left += 1
        right -= 1

    return ''.join(str_list)

