def duplicate_count(text):
    seen = set()
    duplicates = set()
    for char in text.lower():
        if char in seen:
            duplicates.add(char)
        else:
            seen.add(char)
    return len(duplicates)

from collections import Counter

def find_least_unique(arr, k):
    count = Counter(arr)
    for num, freq in sorted(count.items(), key=lambda x: x[1]):
        if k >= freq:
            k -= freq
            del count[num]
        else:
            count[num] -= k
            break
    return len(count)

def max_crossing_subarray(arr):
    max_left_sum = float('-inf')
    left_sum = 0
    max_right_sum = float('-inf')
    right_sum = 0

    # Find the maximum sum for the left part
    for i in range(len(arr) // 2 - 1, -1, -1):
        left_sum += arr[i]
        if left_sum > max_left_sum:
            max_left_sum = left_sum

    # Find the maximum sum for the right part
    for i in range(len(arr) // 2, len(arr)):
        right_sum += arr[i]
        if right_sum > max_right_sum:
            max_right_sum = right_sum

    return max_left_sum + max_right_sum

