def find_max_difference(arr):
    max_diff = -1
    min_element = arr[0]

    for i in range(1, len(arr)):
        diff = arr[i] - min_element
        if diff > max_diff:
            max_diff = diff
        if arr[i] < min_element:
            min_element = arr[i]
    return max_diff

def find_common(A, B):
    if len(A) >= len(B):
        for ii in range(len(B)-1, 0, -1):
            l = len(B[:ii])
            if A[-l:] == B[:ii]:
                return A + B[ii:]
    else:
        for ii in range(len(A)-1, 0, -1):
            if A[ii:] == B[:ii]:
                return A + B[ii:]

    return A+B


def smallest_string_length(A):
    if len(A) == 0:
        return 0
    ans = float('inf')
    for ii in range(len(A)):
        tmp = A[ii]
        for jj in range(len(A)):
            if ii == jj:
                continue
            if tmp in A[jj]:
                tmp = A[jj]
            elif A[jj] not in tmp:
                tmp = find_common(tmp, A[jj])
                if len(tmp) >= ans:
                    break
        ans = min(ans, len(tmp))
    return ans

def is_palindrome_alphanumeric(s: str) -> bool:
    alphanumeric_s = ''.join([char for char in s if char.isalnum()]).lower()
    return alphanumeric_s == alphanumeric_s[::-1]

import collections

def largest_overlap(A, B):
    a = []
    b = []
    d = collections.defaultdict(int)

    rows = len(A)
    cols = len(A[0])

    for i in range(rows):
        for j in range(cols):
            if A[i][j] == 1:
                a.append((i, j))
            if B[i][j] == 1:
                b.append((i, j))

    res = 0
    for x, y in a:
        for i, j in b:
            d[(x - i, y - j)] += 1
            res = max(res, d[(x - i, y - j)])
    return res

class Partition:
    def canPartition(self, nums):
        target = sum(nums)

        if target % 2 == 1:
            return False

        target //= 2

        dp = [0 for _ in range(target + 1)]

        for i in range(len(nums)):
            for j in range(target, nums[i] - 1, -1):
                dp[j] = max(dp[j], dp[j - nums[i]] + nums[i])

        return dp[-1] == target

def can_Partition(nums):
    partition = Partition()
    return partition.canPartition(nums)

from collections import defaultdict

def find_smallest_set_of_vertices(n, edges):
    incoming_node = defaultdict(list)
    for x, y in edges:
        incoming_node[y].append(x)
    res = []
    for i in range(n):
        if not incoming_node[i]:
            res.append(i)
    return res

def power_modulo(base, exponent, module):
    if exponent == 0:
        return 1
    t = power_modulo(base, exponent//2, module) % module
    t = (t*t) % module
    if exponent % 2 == 0:
        return t
    else:
        return ((base % module) * t) % module
